class GeneratorWithClauses(Generator):
    def __init__(self, cell, seed=None, **config):
        super().__init__(cell, seed, **config)

    def next_seed(self) -> int:
        return self.rng.randint(0, 2**32)

    def __next__(self) -> Instance:
        instance = Instance(
            id=f"gen_{self.next_seed()}",
            cell=self.cell,
            seed=self.next_seed(),
            spec=self.config['spec'],
            oracle=self.config['oracle'],
            provenance=Provenance(
                generator='GeneratorWithClauses',
                generator_version='0',
                seed=self.next_seed(),
                source_license=self.config['source_license']
            ),
            resource=self.config['resource']
        )
        return instance

verifier.source:
class TrajectoryVerifier(Verifier):
    version: str = '0'

    def verify(self, trajectory: Trajectory, oracle) -> Verdict:
        has_locale_error = False
        for msg in trajectory.messages:
            if hasattr(msg, 'content') and 'locale' in msg.content:
                has_locale_error = True
                break
        passed = not has_locale_error
        notes = ''
        if has_locale_error:
            notes = 'KeyError: locale detected in messages; Faker may have been called without a locale.'
        return Verdict(passed=passed, notes=notes)

